pt:
//【雪車町】
<voice name='雪車町' class='雪車町' src='voice/ma02/0050620a12'>
//「いやいや、いや……。
//　そいつぁ勘弁して頂けませんかねぇ」
"Ah... Será que eu poderia ficar devendo essa?"

en:
//【長坂】
<voice name='長坂' class='長坂' src='voice/ma02/0050630b45'>
